import requests

BASE_URL = "http://localhost:8000"
TOKEN = "eyJhbGciOiJFUzI1NiIsImtpZCI6ImI4MTI2OWYxLTIxZDgtNGYyZS1iNzE5LWMyMjQwYTg0MGQ5MCIsInR5cCI6IkpXVCJ9..7tnorXc_v1GajgbKOx_eL1YOszeBUfjHR8eD_sTpsMVGd1byScCiaea2NrexKmTDL3dIlmobE5Mqry_s39Blkw"
HEADERS = {"Authorization": f"Bearer {TOKEN}"}
TIMEOUT = 30

def test_get_api_v1_rides_list_driver_rides():
    try:
        response = requests.get(f"{BASE_URL}/api/v1/rides", headers=HEADERS, timeout=TIMEOUT)
    except requests.RequestException as e:
        assert False, f"Request to list driver rides failed: {str(e)}"

    assert response.status_code == 200, f"Expected status code 200 but got {response.status_code}"

    try:
        data = response.json()
    except ValueError:
        assert False, "Response is not valid JSON"

    # The API may return a list or a dict with rides list.
    if isinstance(data, dict):
        # Try to find list of rides in keys
        if "rides" in data and isinstance(data["rides"], list):
            rides_list = data["rides"]
        elif "data" in data and isinstance(data["data"], list):
            rides_list = data["data"]
        else:
            assert False, "Response JSON dict does not contain a list of rides in 'rides' or 'data' keys"
    elif isinstance(data, list):
        rides_list = data
    else:
        assert False, "Response JSON is not a list or dict containing a list"

    for ride in rides_list:
        assert isinstance(ride, dict), "Ride item is not a JSON object"
        assert "id" in ride, "Ride item missing 'id' key"


test_get_api_v1_rides_list_driver_rides()
